pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _test(address _unapproved, address _keep) internal {
        bool logged;
        try c.logCreated(_keep) returns (bool __r) { logged = __r; } catch { return; }
        assertTrue(!logged);
    }

    function testFuzz_test(address _unapproved, address _keep) public {
        vm.assume(_unapproved.code.length == 0 && uint160(_unapproved) > 0xffff && _unapproved != address(this) && _unapproved != address(c) && _unapproved != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _unapproved != 0x000000000000000000636F6e736F6c652e6c6f67 && _unapproved != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _unapproved != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(_keep.code.length == 0 && uint160(_keep) > 0xffff && _keep != address(this) && _keep != address(c) && _keep != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _keep != 0x000000000000000000636F6e736F6c652e6c6f67 && _keep != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _keep != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _test(_unapproved, _keep);
    }

    receive() external payable {}
}
